import Foundation
import XCTest
@testable import NativeHarnessClient

/// Notification-order fixtures for streamed reasoning and command output. Method names and
/// fields follow the App Server schema generated by `codex-cli 0.155.0-alpha.16.4`
/// (`codex app-server generate-json-schema`), unchanged since 0.153.4.
final class CodexTaskReducerStreamingTests: XCTestCase {
    /// Every state these sequences pass through also goes through the conversation projection's
    /// cache (`CodexReducerSteps`).
    private let steps = CodexReducerSteps()
    private var reducer: CodexReducerSteps.Recorder { steps.recording }
    private var sequence: UInt64 = 0

    override func tearDown() {
        steps.assertCacheFollowsEveryStep()
        super.tearDown()
    }

    func testReasoningDeltasAccumulateByPartUntilCompletionReplacesThem() throws {
        var state = try runningTurn()
        XCTAssertTrue(apply("item/started", [
            "turnId": .string("turn-1"),
            "item": .object([
                "id": .string("reasoning-1"), "type": .string("reasoning"),
                "summary": .array([]), "content": .array([])
            ])
        ], to: &state))

        XCTAssertTrue(apply("item/reasoning/summaryPartAdded", [
            "turnId": .string("turn-1"), "itemId": .string("reasoning-1"), "summaryIndex": .integer(0)
        ], to: &state))
        XCTAssertTrue(apply("item/reasoning/summaryTextDelta", [
            "turnId": .string("turn-1"), "itemId": .string("reasoning-1"),
            "delta": .string("**Reading"), "summaryIndex": .integer(0)
        ], to: &state))
        XCTAssertTrue(apply("item/reasoning/summaryTextDelta", [
            "turnId": .string("turn-1"), "itemId": .string("reasoning-1"),
            "delta": .string(" the reducer**"), "summaryIndex": .integer(0)
        ], to: &state))
        // A new part announced by the provider starts empty and adds no visible line yet.
        XCTAssertTrue(apply("item/reasoning/summaryPartAdded", [
            "turnId": .string("turn-1"), "itemId": .string("reasoning-1"), "summaryIndex": .integer(1)
        ], to: &state))
        XCTAssertEqual(try reasoning(in: state).summary, [.string("**Reading the reducer**"), .string("")])
        XCTAssertEqual(
            CodexReasoningProjection.text(from: try reasoning(in: state).summary),
            "**Reading the reducer**"
        )
        XCTAssertTrue(apply("item/reasoning/summaryTextDelta", [
            "turnId": .string("turn-1"), "itemId": .string("reasoning-1"),
            "delta": .string("Checking deltas"), "summaryIndex": .integer(1)
        ], to: &state))
        XCTAssertTrue(apply("item/reasoning/textDelta", [
            "turnId": .string("turn-1"), "itemId": .string("reasoning-1"),
            "delta": .string("raw thought"), "contentIndex": .integer(0)
        ], to: &state))

        let live = try reasoning(in: state)
        XCTAssertEqual(live.summary, [.string("**Reading the reducer**"), .string("Checking deltas")])
        XCTAssertEqual(live.content, [.string("raw thought")])
        XCTAssertEqual(try item("reasoning-1", in: state).lifecycle, .inProgress)

        // The provider's completed item is authoritative even when it differs from the deltas.
        XCTAssertTrue(apply("item/completed", [
            "turnId": .string("turn-1"),
            "item": .object([
                "id": .string("reasoning-1"), "type": .string("reasoning"),
                "summary": .array([.string("**Reading the reducer**"), .string("Checked deltas.")]),
                "content": .array([.string("raw thought, finished")])
            ])
        ], to: &state))
        let completed = try reasoning(in: state)
        XCTAssertEqual(completed.summary, [.string("**Reading the reducer**"), .string("Checked deltas.")])
        XCTAssertEqual(completed.content, [.string("raw thought, finished")])
        XCTAssertEqual(try item("reasoning-1", in: state).lifecycle, .completed)

        XCTAssertFalse(apply("item/reasoning/summaryTextDelta", [
            "turnId": .string("turn-1"), "itemId": .string("reasoning-1"),
            "delta": .string(" late"), "summaryIndex": .integer(1)
        ], to: &state))
        XCTAssertEqual(try reasoning(in: state), completed)
    }

    func testReasoningDeltaOutsideThePartSequenceIsDropped() throws {
        var state = try runningTurn()
        XCTAssertTrue(apply("item/started", [
            "turnId": .string("turn-1"),
            "item": .object([
                "id": .string("reasoning-1"), "type": .string("reasoning"),
                "summary": .array([]), "content": .array([])
            ])
        ], to: &state))
        // Index 0 may begin without an explicit part announcement; a gap may not.
        XCTAssertTrue(apply("item/reasoning/summaryTextDelta", [
            "turnId": .string("turn-1"), "itemId": .string("reasoning-1"),
            "delta": .string("first"), "summaryIndex": .integer(0)
        ], to: &state))
        XCTAssertFalse(apply("item/reasoning/summaryTextDelta", [
            "turnId": .string("turn-1"), "itemId": .string("reasoning-1"),
            "delta": .string("gap"), "summaryIndex": .integer(2)
        ], to: &state))
        XCTAssertFalse(apply("item/reasoning/textDelta", [
            "turnId": .string("turn-1"), "itemId": .string("reasoning-1"),
            "delta": .string("negative"), "contentIndex": .integer(-1)
        ], to: &state))
        // A repeated announcement of an existing part changes nothing.
        XCTAssertFalse(apply("item/reasoning/summaryPartAdded", [
            "turnId": .string("turn-1"), "itemId": .string("reasoning-1"), "summaryIndex": .integer(0)
        ], to: &state))
        XCTAssertEqual(try reasoning(in: state).summary, [.string("first")])
        XCTAssertEqual(try reasoning(in: state).content, [])
    }

    func testCommandOutputStreamsIntoTheRunningCardAndCompletionWins() throws {
        var state = try runningTurn()
        XCTAssertTrue(apply("item/started", [
            "turnId": .string("turn-1"),
            "item": commandItem(status: "inProgress", output: nil)
        ], to: &state))
        for delta in ["Building\n", "Compiling 1/2\n", "Compiling 2/2\n"] {
            XCTAssertTrue(apply("item/commandExecution/outputDelta", [
                "turnId": .string("turn-1"), "itemId": .string("command-1"), "delta": .string(delta)
            ], to: &state))
        }
        let live = try command(in: state)
        XCTAssertEqual(live.aggregatedOutput, "Building\nCompiling 1/2\nCompiling 2/2\n")
        XCTAssertEqual(live.status, "inProgress")
        // The provider frame stays as received; the streamed text lives in typed content.
        XCTAssertEqual(try item("command-1", in: state).raw["aggregatedOutput"], .null)
        XCTAssertEqual(
            try item("command-1", in: state).renderedPayload["aggregatedOutput"]?.stringValue,
            "Building\nCompiling 1/2\nCompiling 2/2\n"
        )

        // The completed value differs from the delta sum and replaces it without duplication.
        XCTAssertTrue(apply("item/completed", [
            "turnId": .string("turn-1"),
            "item": commandItem(status: "completed", output: "Build complete\n", exitCode: 0)
        ], to: &state))
        let completed = try command(in: state)
        XCTAssertEqual(completed.aggregatedOutput, "Build complete\n")
        XCTAssertEqual(completed.status, "completed")
        XCTAssertEqual(completed.exitCode, 0)

        XCTAssertFalse(apply("item/commandExecution/outputDelta", [
            "turnId": .string("turn-1"), "itemId": .string("command-1"), "delta": .string("late\n")
        ], to: &state))
        XCTAssertEqual(try command(in: state).aggregatedOutput, "Build complete\n")
    }

    func testCompletionWithoutDeltasCarriesTheFinalValues() throws {
        var state = try runningTurn()
        XCTAssertTrue(apply("item/completed", [
            "turnId": .string("turn-1"),
            "item": commandItem(status: "completed", output: "only final\n", exitCode: 0)
        ], to: &state))
        XCTAssertTrue(apply("item/completed", [
            "turnId": .string("turn-1"),
            "item": .object([
                "id": .string("reasoning-1"), "type": .string("reasoning"),
                "summary": .array([.string("Summary only")]), "content": .array([])
            ])
        ], to: &state))
        XCTAssertEqual(try command(in: state).aggregatedOutput, "only final\n")
        XCTAssertEqual(try reasoning(in: state).summary, [.string("Summary only")])
        XCTAssertNil(CodexReasoningProjection.text(from: try reasoning(in: state).content))
        // A completed item needs no rendered override on the YHP route.
        XCTAssertEqual(try item("command-1", in: state).renderedPayload, try item("command-1", in: state).raw)
        XCTAssertEqual(try item("reasoning-1", in: state).renderedPayload, try item("reasoning-1", in: state).raw)
    }

    func testDeltasForUnknownItemsCreateNoTurnOrCard() throws {
        var state = try runningTurn()
        let before = state.thread
        XCTAssertFalse(apply("item/commandExecution/outputDelta", [
            "turnId": .string("turn-1"), "itemId": .string("missing"), "delta": .string("orphan")
        ], to: &state))
        XCTAssertFalse(apply("item/reasoning/summaryTextDelta", [
            "turnId": .string("turn-1"), "itemId": .string("missing"),
            "delta": .string("orphan"), "summaryIndex": .integer(0)
        ], to: &state))
        XCTAssertFalse(apply("item/reasoning/summaryPartAdded", [
            "turnId": .string("other-turn"), "itemId": .string("missing"), "summaryIndex": .integer(0)
        ], to: &state))
        XCTAssertFalse(apply("item/reasoning/textDelta", [
            "turnId": .string("other-turn"), "itemId": .string("missing"),
            "delta": .string("orphan"), "contentIndex": .integer(0)
        ], to: &state))
        XCTAssertEqual(state.thread, before)

        // A delta addressed to an item of another kind is ignored as well.
        XCTAssertTrue(apply("item/started", [
            "turnId": .string("turn-1"),
            "item": .object([
                "id": .string("answer"), "type": .string("agentMessage"), "text": .string("Hi")
            ])
        ], to: &state))
        XCTAssertFalse(apply("item/commandExecution/outputDelta", [
            "turnId": .string("turn-1"), "itemId": .string("answer"), "delta": .string("wrong kind")
        ], to: &state))
        XCTAssertFalse(apply("item/reasoning/textDelta", [
            "turnId": .string("turn-1"), "itemId": .string("answer"),
            "delta": .string("wrong kind"), "contentIndex": .integer(0)
        ], to: &state))
        guard case let .agentMessage(message) = try item("answer", in: state).content else {
            return XCTFail("agent message should keep its kind")
        }
        XCTAssertEqual(message.text, "Hi")
    }

    /// A long-running command keeps streaming: the card holds its first lines and its latest
    /// ones, so the newest output is never the part that is dropped.
    func testLiveCommandOutputKeepsItsFirstAndLatestLinesUntilCompletion() throws {
        var state = try runningTurn()
        XCTAssertTrue(apply("item/started", [
            "turnId": .string("turn-1"),
            "item": commandItem(status: "inProgress", output: nil)
        ], to: &state))
        let lineCount = 12_000
        var accepted = 0
        var headAfterFirstCut: String?
        for index in 1...lineCount {
            if apply("item/commandExecution/outputDelta", [
                "turnId": .string("turn-1"), "itemId": .string("command-1"),
                "delta": .string(String(format: "Compiling module %05d of %05d\n", index, lineCount))
            ], to: &state) { accepted += 1 }
            if headAfterFirstCut == nil, let output = try command(in: state).aggregatedOutput,
               let marker = output.range(of: CodexLiveCommandOutput.truncationLine) {
                headAfterFirstCut = String(output[..<marker.lowerBound])
            }
        }
        XCTAssertEqual(accepted, lineCount)
        let live = try command(in: state)
        let output = try XCTUnwrap(live.aggregatedOutput)
        XCTAssertLessThanOrEqual(
            output.utf8.count, CodexLiveCommandOutput.limit + CodexLiveCommandOutput.truncationLine.utf8.count
        )
        XCTAssertGreaterThan(output.utf8.count, CodexLiveCommandOutput.limit / 2)
        XCTAssertTrue(output.hasPrefix("Compiling module 00001 of 12000\n"))
        XCTAssertTrue(output.hasSuffix("Compiling module 12000 of 12000\n"))
        XCTAssertEqual(output.components(separatedBy: CodexLiveCommandOutput.truncationLine).count, 2)
        // The head stays as it was cut, and head and tail each hold whole lines.
        let parts = output.components(separatedBy: CodexLiveCommandOutput.truncationLine)
        XCTAssertEqual(parts[0], headAfterFirstCut)
        XCTAssertEqual(live.liveOutputHeadByteCount, parts[0].utf8.count)
        for line in (parts[0] + parts[1]).split(separator: "\n") {
            XCTAssertTrue(line.hasPrefix("Compiling module "), "partial line kept: \(line)")
        }

        let full = String(repeating: "y", count: CodexLiveCommandOutput.limit * 2)
        XCTAssertTrue(apply("item/completed", [
            "turnId": .string("turn-1"),
            "item": commandItem(status: "completed", output: full, exitCode: 0)
        ], to: &state))
        XCTAssertEqual(try command(in: state).aggregatedOutput, full)
        XCTAssertNil(try command(in: state).liveOutputHeadByteCount)
    }

    /// Progress output without line breaks, and characters wider than one byte, are cut only on
    /// character boundaries.
    func testLiveCommandOutputCutsUnbrokenAndMultibyteOutputOnCharacters() throws {
        var state = try runningTurn()
        XCTAssertTrue(apply("item/started", [
            "turnId": .string("turn-1"),
            "item": commandItem(status: "inProgress", output: nil)
        ], to: &state))
        let unit = "한글👩🏽‍💻\r"
        for index in 0..<4_000 {
            XCTAssertTrue(apply("item/commandExecution/outputDelta", [
                "turnId": .string("turn-1"), "itemId": .string("command-1"),
                "delta": .string(index == 3_999 ? "done" : String(repeating: unit, count: 3))
            ], to: &state))
        }
        let output = try XCTUnwrap(try command(in: state).aggregatedOutput)
        XCTAssertLessThanOrEqual(
            output.utf8.count, CodexLiveCommandOutput.limit + CodexLiveCommandOutput.truncationLine.utf8.count + 1
        )
        XCTAssertTrue(output.hasSuffix("done"))
        let parts = output.components(separatedBy: CodexLiveCommandOutput.truncationLine)
        XCTAssertEqual(parts.count, 2)
        XCTAssertTrue(parts[0].hasPrefix("한글👩🏽‍💻"))
        // A carriage return is a line break, so the tail starts on a whole unit.
        XCTAssertTrue(parts[1].hasPrefix("한글👩🏽‍💻"))
    }

    // MARK: - Plan mode

    func testPlanDeltasStreamIntoTheStartedPlanAndCompletionWins() throws {
        var state = try runningTurn()
        XCTAssertTrue(apply("item/started", [
            "turnId": .string("turn-1"),
            "item": .object(["id": .string("plan-1"), "type": .string("plan"), "text": .string("")])
        ], to: &state))
        for delta in ["# Plan\n", "1. Read the reducer\n", "2. Add tests"] {
            XCTAssertTrue(apply("item/plan/delta", [
                "turnId": .string("turn-1"), "itemId": .string("plan-1"), "delta": .string(delta)
            ], to: &state))
        }
        guard case let .plan(live) = try item("plan-1", in: state).content else {
            return XCTFail("plan item should keep its kind")
        }
        XCTAssertEqual(live, "# Plan\n1. Read the reducer\n2. Add tests")
        // YHP rebuilds items from the rendered payload; the streamed text must ride along.
        XCTAssertEqual(try item("plan-1", in: state).renderedPayload["text"]?.stringValue, live)
        XCTAssertTrue(CodexTaskReducer.streamingTextMethods.contains("item/plan/delta"))

        XCTAssertFalse(apply("item/plan/delta", [
            "turnId": .string("turn-1"), "itemId": .string("missing"), "delta": .string("orphan")
        ], to: &state))
        XCTAssertTrue(apply("item/completed", [
            "turnId": .string("turn-1"),
            "item": .object(["id": .string("plan-1"), "type": .string("plan"), "text": .string("# Final plan")])
        ], to: &state))
        XCTAssertFalse(apply("item/plan/delta", [
            "turnId": .string("turn-1"), "itemId": .string("plan-1"), "delta": .string(" late")
        ], to: &state))
        guard case let .plan(final) = try item("plan-1", in: state).content else {
            return XCTFail("plan item should keep its kind")
        }
        XCTAssertEqual(final, "# Final plan")
    }

    // MARK: - Notices
    //
    // `ModelReroutedNotification`, `WarningNotification`, `ConfigWarningNotification`, and
    // `DeprecationNoticeNotification` as the App Server sends them.

    func testRerouteAndWarningsShowOnceInTheirTurn() throws {
        var state = try runningTurn()
        let reroute: [String: JSONValue] = [
            "turnId": .string("turn-1"), "fromModel": .string("gpt-5.5"),
            "toModel": .string("gpt-5.5-mini"), "reason": .string("highRiskCyberActivity")
        ]
        XCTAssertTrue(apply("model/rerouted", reroute, to: &state))
        XCTAssertFalse(apply("model/rerouted", reroute, to: &state))
        XCTAssertTrue(apply("warning", ["message": .string("Under-development features enabled: memories")], to: &state))

        let notices = try XCTUnwrap(state.thread?.turns.first?.items).compactMap { item -> CodexNoticeItem? in
            guard case let .notice(notice) = item.content else { return nil }
            XCTAssertEqual(item.lifecycle, .completed)
            // A notice item needs no rendered override to cross YHP.
            XCTAssertEqual(item.renderedPayload, item.raw)
            XCTAssertEqual(CodexTaskDecoder().item(from: item.raw, fallbackID: "x", lifecycle: .completed).content, item.content)
            return notice
        }
        XCTAssertEqual(notices, [
            CodexNoticeItem(kind: .modelRerouted, message: "gpt-5.5-mini", details: nil, fromModel: "gpt-5.5",
                            reason: "highRiskCyberActivity", path: nil),
            CodexNoticeItem(kind: .warning, message: "Under-development features enabled: memories", details: nil,
                            fromModel: nil, reason: nil, path: nil)
        ])
        XCTAssertTrue(CodexItemContent.notice(notices[0]).shouldPersistAcrossResume)

        // A notice addressed to another thread changes nothing.
        let before = state.thread
        sequence += 1
        XCTAssertFalse(reducer.applyNotification(
            method: "warning",
            params: .object(["threadId": .string("other-thread"), "message": .string("elsewhere")]),
            sequence: sequence, to: &state
        ))
        XCTAssertEqual(state.thread, before)
    }

    func testANoticeWhileIdleWaitsForTheNextTurn() throws {
        var state = try runningTurn()
        XCTAssertTrue(apply("turn/completed", [
            "turn": .object(["id": .string("turn-1"), "status": .string("completed")])
        ], to: &state))
        XCTAssertTrue(apply("configWarning", [
            "summary": .string("Unknown key `foo` in config.toml"),
            "details": .string("Remove it or check the spelling."),
            "path": .string("/Users/me/.codex/config.toml")
        ], to: &state))
        XCTAssertTrue(apply("deprecationNotice", ["summary": .string("`experimental_instructions_file` is deprecated")],
                          to: &state))
        XCTAssertEqual(state.pendingNotices.count, 2)
        XCTAssertEqual(state.thread?.turns.first?.items.count, 0)

        XCTAssertTrue(apply("turn/started", [
            "turn": .object(["id": .string("turn-2"), "status": .string("inProgress"), "items": .array([])])
        ], to: &state))
        XCTAssertEqual(state.pendingNotices, [])
        let kinds = (state.thread?.turns.last?.items ?? []).compactMap { item -> CodexNoticeItem.Kind? in
            guard case let .notice(notice) = item.content else { return nil }
            return notice.kind
        }
        XCTAssertEqual(kinds, [.configWarning, .deprecationNotice])
        guard case let .notice(config) = state.thread?.turns.last?.items.first?.content else {
            return XCTFail("config warning should open the next turn")
        }
        XCTAssertEqual(config.details, "Remove it or check the spelling.")
        XCTAssertEqual(config.path, "/Users/me/.codex/config.toml")
    }

    func testANoticeBeforeTheThreadLoadsWaitsWithoutOpeningAThread() {
        var state = CodexTaskState.empty
        XCTAssertTrue(apply("configWarning", ["summary": .string("Invalid profile")], to: &state))
        XCTAssertNil(state.thread)
        XCTAssertEqual(state.pendingNotices.count, 1)
    }

    func testTurnEndingMidStreamKeepsStreamedOutputOnTheInterruptedCard() throws {
        var state = try runningTurn()
        XCTAssertTrue(apply("item/started", [
            "turnId": .string("turn-1"),
            "item": commandItem(status: "inProgress", output: nil)
        ], to: &state))
        XCTAssertTrue(apply("item/commandExecution/outputDelta", [
            "turnId": .string("turn-1"), "itemId": .string("command-1"), "delta": .string("partial\n")
        ], to: &state))
        XCTAssertTrue(apply("turn/completed", [
            "turn": .object(["id": .string("turn-1"), "status": .string("interrupted")])
        ], to: &state))

        let interrupted = try item("command-1", in: state)
        XCTAssertEqual(interrupted.lifecycle, .completed)
        guard case let .commandExecution(command) = interrupted.content else {
            return XCTFail("interrupted item should remain a command card")
        }
        XCTAssertEqual(command.status, "interrupted")
        XCTAssertEqual(command.aggregatedOutput, "partial\n")
        XCTAssertEqual(interrupted.raw["status"]?.stringValue, "interrupted")
    }

    // MARK: - Patch updates and MCP progress
    //
    // `FileChangePatchUpdatedNotification` and `McpToolCallProgressNotification` as generated by
    // `codex-cli 0.158.0-alpha.2.1` (`app-server generate-json-schema --experimental`).

    func testPatchUpdatesReplaceTheRunningFileChangeCardAndCompletionWins() throws {
        var state = try runningTurn()
        XCTAssertTrue(apply("item/started", [
            "turnId": .string("turn-1"),
            "item": fileChangeItem(status: "inProgress", changes: [])
        ], to: &state))

        let first = [patchChange("Sources/App.swift", kind: "update", diff: "@@ -1 +1 @@\n-a\n+b\n")]
        XCTAssertTrue(apply("item/fileChange/patchUpdated", [
            "turnId": .string("turn-1"), "itemId": .string("patch-1"), "changes": .array(first)
        ], to: &state))
        XCTAssertEqual(try fileChange(in: state).changes, first)
        XCTAssertEqual(try fileChange(in: state).status, "inProgress")
        XCTAssertEqual(try item("patch-1", in: state).lifecycle, .inProgress)
        // The provider frame stays as received; the streamed patch crosses as the rendered payload.
        XCTAssertEqual(try item("patch-1", in: state).raw["changes"], .array([]))
        XCTAssertEqual(try item("patch-1", in: state).renderedPayload["changes"], .array(first))

        // Each update carries the whole patch so far, so it replaces rather than appends.
        let second = [
            patchChange("Sources/App.swift", kind: "update", diff: "@@ -1,2 +1,2 @@\n-a\n+b\n c\n"),
            patchChange("Sources/New.swift", kind: "add", diff: "+struct New {}\n")
        ]
        XCTAssertTrue(apply("item/fileChange/patchUpdated", [
            "turnId": .string("turn-1"), "itemId": .string("patch-1"), "changes": .array(second)
        ], to: &state))
        XCTAssertEqual(try fileChange(in: state).changes, second)
        XCTAssertEqual(
            CodexWorkSurfaceProjection.changes(from: state, workspaceURL: URL(filePath: "/tmp/workspace"))
                .map(\.relativePath),
            ["Sources/App.swift", "Sources/New.swift"]
        )
        // An identical update changes nothing and publishes nothing.
        XCTAssertFalse(apply("item/fileChange/patchUpdated", [
            "turnId": .string("turn-1"), "itemId": .string("patch-1"), "changes": .array(second)
        ], to: &state))

        let final = [patchChange("Sources/App.swift", kind: "update", diff: "@@ -1 +1 @@\n-a\n+z\n")]
        XCTAssertTrue(apply("item/completed", [
            "turnId": .string("turn-1"),
            "item": fileChangeItem(status: "completed", changes: final)
        ], to: &state))
        XCTAssertEqual(try fileChange(in: state).changes, final)
        XCTAssertEqual(try fileChange(in: state).status, "completed")
        XCTAssertEqual(try item("patch-1", in: state).renderedPayload, try item("patch-1", in: state).raw)

        XCTAssertFalse(apply("item/fileChange/patchUpdated", [
            "turnId": .string("turn-1"), "itemId": .string("patch-1"), "changes": .array(second)
        ], to: &state))
        XCTAssertEqual(try fileChange(in: state).changes, final)
    }

    func testPatchUpdateBeforeTheItemStartsOpensAnInProgressFileChangeCard() throws {
        var state = try runningTurn()
        let streamed = [patchChange("README.md", kind: "update", diff: "+Line\n")]
        XCTAssertTrue(apply("item/fileChange/patchUpdated", [
            "turnId": .string("turn-1"), "itemId": .string("patch-1"), "changes": .array(streamed)
        ], to: &state))
        let opened = try item("patch-1", in: state)
        XCTAssertEqual(opened.lifecycle, .inProgress)
        XCTAssertEqual(try fileChange(in: state), CodexFileChangeItem(changes: streamed, status: "inProgress"))

        // The provider's own frame replaces the opened card.
        let started = [
            patchChange("README.md", kind: "update", diff: "+Line\n"),
            patchChange("docs/Old.md", kind: "delete", diff: "-Old\n")
        ]
        XCTAssertTrue(apply("item/started", [
            "turnId": .string("turn-1"),
            "item": fileChangeItem(status: "inProgress", changes: started)
        ], to: &state))
        XCTAssertEqual(try fileChange(in: state).changes, started)
        XCTAssertEqual(state.thread?.turns.first?.items.filter { $0.id == "patch-1" }.count, 1)

        // An unknown turn gets no phantom turn or card, and another kind of item is left alone.
        let before = state.thread
        XCTAssertFalse(apply("item/fileChange/patchUpdated", [
            "turnId": .string("other-turn"), "itemId": .string("patch-2"), "changes": .array(streamed)
        ], to: &state))
        XCTAssertEqual(state.thread, before)
        XCTAssertTrue(apply("item/started", [
            "turnId": .string("turn-1"),
            "item": commandItem(status: "inProgress", output: nil)
        ], to: &state))
        XCTAssertFalse(apply("item/fileChange/patchUpdated", [
            "turnId": .string("turn-1"), "itemId": .string("command-1"), "changes": .array(streamed)
        ], to: &state))
        XCTAssertEqual(try command(in: state).command, "swift build")
    }

    func testMCPProgressNotesAreLeftOffTheToolCardAsInTheCodexApp() throws {
        var state = try runningTurn()
        XCTAssertTrue(apply("item/started", [
            "turnId": .string("turn-1"),
            "item": mcpItem(status: "inProgress", result: nil)
        ], to: &state))
        let before = state.thread
        XCTAssertFalse(apply("item/mcpToolCall/progress", [
            "turnId": .string("turn-1"), "itemId": .string("mcp-1"), "message": .string("Indexing 2 of 3")
        ], to: &state))
        XCTAssertEqual(state.thread, before)
    }

    func testStreamingMethodsAreTheOnesWhosePublicationsCoalesce() {
        XCTAssertEqual(CodexTaskReducer.streamingTextMethods, [
            "item/agentMessage/delta",
            "item/reasoning/summaryPartAdded",
            "item/reasoning/summaryTextDelta",
            "item/reasoning/textDelta",
            "item/plan/delta",
            "item/commandExecution/outputDelta",
            "item/fileChange/patchUpdated",
            "turn/diff/updated"
        ])
        XCTAssertFalse(CodexTaskReducer.streamingTextMethods.contains("item/completed"))
        XCTAssertFalse(CodexTaskReducer.streamingTextMethods.contains("turn/completed"))
    }

    func testReasoningProjectionOmitsEmptyAndWithheldContent() {
        XCTAssertNil(CodexReasoningProjection.text(from: []))
        XCTAssertNil(CodexReasoningProjection.text(from: [.string(""), .string(" \n")]))
        // Only provider text is shown; an opaque or encrypted value is not text.
        XCTAssertNil(CodexReasoningProjection.text(from: [.object(["encrypted": .string("gAAA")])]))
        XCTAssertEqual(
            CodexReasoningProjection.text(from: [.string("First"), .string(""), .string("Second")]),
            "First\nSecond"
        )
    }

    // MARK: - Fixtures

    private func runningTurn() throws -> CodexTaskState {
        var state = CodexTaskState.empty
        XCTAssertTrue(reducer.applySnapshot(.object([
            "id": .string("thread-1"), "preview": .string(""),
            "status": .object(["type": .string("active"), "activeFlags": .array([])]),
            "turns": .array([])
        ]), to: &state))
        XCTAssertTrue(apply("turn/started", [
            "turn": .object(["id": .string("turn-1"), "status": .string("inProgress"), "items": .array([])])
        ], to: &state))
        return state
    }

    private func apply(
        _ method: String,
        _ params: [String: JSONValue],
        to state: inout CodexTaskState
    ) -> Bool {
        sequence += 1
        var params = params
        params["threadId"] = .string("thread-1")
        return reducer.applyNotification(
            method: method,
            params: .object(params),
            sequence: sequence,
            to: &state
        )
    }

    private func commandItem(status: String, output: String?, exitCode: Int64? = nil) -> JSONValue {
        .object([
            "id": .string("command-1"), "type": .string("commandExecution"),
            "command": .string("swift build"), "cwd": .string("/tmp/workspace"),
            "processId": .null, "source": .string("agent"), "status": .string(status),
            "commandActions": .array([]),
            "aggregatedOutput": output.map(JSONValue.string) ?? .null,
            "exitCode": exitCode.map(JSONValue.integer) ?? .null,
            "durationMs": .null
        ])
    }

    private func fileChangeItem(status: String, changes: [JSONValue]) -> JSONValue {
        .object([
            "id": .string("patch-1"), "type": .string("fileChange"),
            "changes": .array(changes), "status": .string(status)
        ])
    }

    private func patchChange(_ path: String, kind: String, diff: String) -> JSONValue {
        var kindValue: [String: JSONValue] = ["type": .string(kind)]
        if kind == "update" { kindValue["move_path"] = .null }
        return .object(["path": .string(path), "kind": .object(kindValue), "diff": .string(diff)])
    }

    private func mcpItem(status: String, result: JSONValue?) -> JSONValue {
        .object([
            "id": .string("mcp-1"), "type": .string("mcpToolCall"),
            "server": .string("docs"), "tool": .string("index"),
            "arguments": .object(["path": .string("/tmp/workspace")]),
            "status": .string(status),
            "result": result ?? .null, "error": .null, "durationMs": .null
        ])
    }

    private func fileChange(in state: CodexTaskState) throws -> CodexFileChangeItem {
        guard case let .fileChange(change) = try item("patch-1", in: state).content else {
            throw UnexpectedItem(description: "patch-1 is not a file change card")
        }
        return change
    }

    private func item(_ id: String, in state: CodexTaskState) throws -> CodexItemState {
        try XCTUnwrap(state.thread?.turns.flatMap(\.items).first { $0.id == id })
    }

    private func command(in state: CodexTaskState) throws -> CodexCommandItem {
        guard case let .commandExecution(command) = try item("command-1", in: state).content else {
            throw UnexpectedItem(description: "command-1 is not a command card")
        }
        return command
    }

    private func reasoning(in state: CodexTaskState) throws -> ReasoningParts {
        guard case let .reasoning(summary, content) = try item("reasoning-1", in: state).content else {
            throw UnexpectedItem(description: "reasoning-1 is not a reasoning card")
        }
        return ReasoningParts(summary: summary, content: content)
    }

    private struct UnexpectedItem: Error, CustomStringConvertible {
        let description: String
    }

    private struct ReasoningParts: Equatable {
        let summary: [JSONValue]
        let content: [JSONValue]
    }
}
